-- attribute means for NFL players overall>=74: early (2025-27) vs late (2032-34), by unit and attribute index
rsql with p as (select lp.season s, case when lp.person__player__position in ('OT','IOL') then 'OL' when lp.person__player__position in ('DT','EDGE') then 'DL' when lp.person__player__position in ('CB','S') then 'DB' else lp.person__player__position end u, more('log_players', lp._more) m from log_players lp where lp.level = 'NFL' and lp.overall >= 74 and ((lp.season between 2025 and 2027) or (lp.season between 2032 and 2034)) and lp.person__player__position in ('OT','IOL','DT','EDGE','LB','CB','S','RB')) select u, a.key idx, case when s <= 2027 then 'early' else 'late' end per, count(*) n, round(avg(a.value)/10,2) mean from p, json_each(p.m, '$.person.player.attributes_x10') a group by u, idx, per order by u, idx, per
